'use strict';
document.querySelector('.upload-panel').insertAdjacentHTML('beforeend','<div class="draft-storage"><span id="draft-status" role="status" aria-live="polite">正在检查本地记录…</span><button type="button" id="clear-draft" hidden>清除本地记录</button></div>');
document.querySelector('.editor-local-note').textContent='航班记录自动保存在此浏览器，也可导出 Excel 备份。';
const draftStatus=$('draft-status'),clearDraft=$('clear-draft');
let restoringDraft=false,draftReadFinished=false,draftTouched=false,draftEpoch=0,draftWrites=Promise.resolve(),draftFailed=false;
const draftDB=new Promise((resolve,reject)=>{let req;try{req=indexedDB.open('flight-atlas-local',1);}catch(e){reject(e);return;}req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('drafts'))req.result.createObjectStore('drafts');};req.onsuccess=()=>{const db=req.result;db.onversionchange=()=>db.close();resolve(db);};req.onerror=()=>reject(req.error||Error('IndexedDB unavailable'));req.onblocked=()=>reject(Error('Local database blocked'));});
function storageNotice(message,bad=false){draftStatus.textContent=message;draftStatus.classList.toggle('storage-error',bad);}
function storageFailure(){draftFailed=true;storageNotice('本地保存不可用，请导出 Excel 保留修改。',true);}
function localSnapshot(){const sheets=state.sheets||[];const active=sheets.findIndex(s=>s.rows===state.rows);return structuredClone({version:1,savedAt:new Date().toISOString(),sheets,activeSheet:active,rows:active<0?state.rows:null,fileName:state.fileName,demo:state.demo,layout:state.layout,labelSelection:state.labelSelection,colors:atlasColors(state.colors),cutoff:validDate($('cutoff').value)?$('cutoff').value:localDate(),includeFuture:$('future').checked});}
function draftTransaction(db,mode,operation){return new Promise((resolve,reject)=>{let tx;try{tx=db.transaction('drafts',mode);operation(tx.objectStore('drafts'));}catch(e){reject(e);return;}tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error||Error('Save failed'));tx.onabort=()=>reject(tx.error||Error('Save aborted'));});}
function saveLocalDraft(){if(restoringDraft)return;draftTouched=true;const epoch=draftEpoch;let snapshot;try{snapshot=localSnapshot();}catch(e){storageFailure();return;}storageNotice('正在自动保存…');draftWrites=draftWrites.catch(()=>{}).then(async()=>{if(epoch!==draftEpoch)return;const db=await draftDB;if(epoch!==draftEpoch)return;await draftTransaction(db,'readwrite',store=>store.put(snapshot,'current'));if(epoch!==draftEpoch)return;draftFailed=false;storageNotice('已自动保存 · 仅在此浏览器');clearDraft.hidden=false;}).catch(()=>{if(epoch===draftEpoch)storageFailure();});}
function validSnapshot(draft){return draft&&draft.version===1&&Array.isArray(draft.sheets)&&draft.sheets.every(s=>s&&typeof s.name==='string'&&Array.isArray(s.rows))&&(draft.rows===null||Array.isArray(draft.rows))&&['portrait','landscape'].includes(draft.layout)&&validDate(draft.cutoff);}
async function restoreLocalDraft(){try{const db=await draftDB;const draft=await new Promise((resolve,reject)=>{const req=db.transaction('drafts','readonly').objectStore('drafts').get('current');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});if(draftTouched||state.rows!==null)return;if(!draft){storageNotice('自动保存已开启 · 仅在此浏览器');return;}if(!validSnapshot(draft)){storageNotice('本地记录格式无法读取，可清除后重新导入。',true);clearDraft.hidden=false;return;}
 restoringDraft=true;state.sheets=draft.sheets;state.rows=draft.activeSheet>=0&&draft.activeSheet<draft.sheets.length?draft.sheets[draft.activeSheet].rows:draft.rows;state.fileName=typeof draft.fileName==='string'?draft.fileName:'';state.demo=!!draft.demo;state.layout='portrait';state.colors=atlasColors(draft.colors);syncAtlasColorControls();state.labelSelection=Array.isArray(draft.labelSelection)?[...new Set(draft.labelSelection.filter(c=>typeof c==='string'&&/^[A-Z]{3}$/.test(c)))]:null;$('cutoff').value=draft.cutoff;$('future').checked=!!draft.includeFuture;
 document.querySelectorAll('[data-layout]').forEach(b=>{const selected=b.dataset.layout===state.layout;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected));});updateSize();$('file-info').textContent=state.fileName||'支持 Flighty 导出及常见中文列名；导入会替换当前记录。';$('sheet-wrap').hidden=state.sheets.length<2;$('sheet').replaceChildren(...state.sheets.map((s,i)=>new Option(s.name,String(i))));if(draft.activeSheet>=0)$('sheet').value=String(draft.activeSheet);
 if(state.rows!==null)await regenerate();storageNotice('已恢复上次记录 · 后续修改自动保存');clearDraft.hidden=false;
 }catch(e){storageFailure();}finally{restoringDraft=false;draftReadFinished=true;}}
window.addEventListener('atlas:rows',()=>{if(!restoringDraft)saveLocalDraft();});
for(const id of ['cutoff','future'])$(id).addEventListener('change',()=>{if(!restoringDraft)saveLocalDraft();});
document.querySelectorAll('[data-layout]').forEach(b=>b.addEventListener('click',()=>{if(!restoringDraft)saveLocalDraft();}));
// Do not overwrite a new upload with a late restore, even while its file is being parsed.
$('file').addEventListener('change',()=>{draftTouched=true;});$('dropzone').addEventListener('drop',()=>{draftTouched=true;});$('manual-start').addEventListener('click',()=>{draftTouched=true;});$('add-record').addEventListener('click',()=>{draftTouched=true;});
clearDraft.addEventListener('click',async()=>{if(!confirm('清除当前浏览器保存的航班记录与设置？已下载的 Excel 和图片不会被删除。'))return;const epoch=++draftEpoch;draftTouched=true;clearDraft.disabled=true;restoringDraft=true;try{await draftWrites.catch(()=>{});const db=await draftDB;await draftTransaction(db,'readwrite',store=>store.delete('current'));if(epoch!==draftEpoch)return;state.rows=null;state.sheets=[];state.fileName='';state.demo=false;state.layout='portrait';state.labelSelection=null;state.colors=atlasColors(null);syncAtlasColorControls();$('cutoff').value=localDate();$('future').checked=false;$('file').value='';$('sheet').replaceChildren();$('sheet-wrap').hidden=true;$('file-info').textContent='支持 Flighty 导出及常见中文列名；导入会替换当前记录。';$('record-search').value='';$('record-filter').value='all';document.querySelectorAll('[data-layout]').forEach(b=>{const selected=b.dataset.layout==='portrait';b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected));});updateSize();await regenerate();storageNotice('本地记录已清除 · 新记录仍会自动保存');clearDraft.hidden=true;}catch(e){storageNotice('清除失败，请稍后重试或在浏览器中清除本站数据。',true);}finally{restoringDraft=false;clearDraft.disabled=false;}});
draftDB.catch(()=>{});restoreLocalDraft();

